/* ===================== bases de dados: esquema, linhas, visões ===================== */
const TIPOS_PROP=[['texto','Texto'],['numero','Número'],['select','Seleção'],['multi','Multi-seleção'],['status','Status'],['data','Data'],['pessoa','Pessoa'],['checkbox','Checkbox'],['url','URL'],['email','E-mail'],['telefone','Telefone'],['arquivos','Arquivos'],['relacao','Relação'],['criado_em','Criado em'],['atualizado_em','Atualizado em']];
const CORES_TAG=['gray','brown','orange','yellow','green','blue','purple','pink','red'];
const corAleatoria=()=>CORES_TAG[Math.floor(Math.random()*CORES_TAG.length)];
function baseEsquemaPadrao(){return {props:[{id:'status',nome:'Status',tipo:'status',opcoes:[{id:'a',nome:'A fazer',cor:'gray'},{id:'b',nome:'Em andamento',cor:'blue'},{id:'c',nome:'Concluído',cor:'green'}]},{id:'resp',nome:'Responsável',tipo:'pessoa'},{id:'prazo',nome:'Prazo',tipo:'data'}]};}
function baseVisoesPadrao(){return [{id:'v1',nome:'Tabela',tipo:'tabela',props:null},{id:'v2',nome:'Kanban',tipo:'kanban',agrupar:'status'}];}
const arr=v=>v==null||v===''?[]:Array.isArray(v)?v:[v];
const B={};   // estado da base montada: {host, base, linhas, visao, opts}

function propsDe(base){return ((base.esquema&&base.esquema.props)||[]);}
function propPorId(base,id){return propsDe(base).find(p=>p.id===id);}
function opcaoDe(prop,v){if(!prop||!prop.opcoes)return null;return prop.opcoes.find(o=>o.id===v||o.nome===v)||null;}
function valorTexto(prop,v,linha){if(prop.tipo==='criado_em')return fmtData(linha.criado_em,true);if(prop.tipo==='atualizado_em')return fmtData(linha.atualizado_em,true);if(v==null||v==='')return '';
  switch(prop.tipo){case 'select':case 'status':{const o=opcaoDe(prop,v);return o?o.nome:String(v);}case 'multi':return arr(v).map(x=>{const o=opcaoDe(prop,x);return o?o.nome:x;}).join(', ');case 'data':return typeof v==='object'?fmtData(v.inicio,v.hora)+(v.fim?' → '+fmtData(v.fim,v.hora):''):fmtData(v);case 'pessoa':return arr(v).map(nomeMembro).join(', ');case 'checkbox':return v?'Sim':'Não';case 'numero':return fmtNum(v,prop.formato);case 'arquivos':return arr(v).map(a=>a&&a.nome||'').join(', ');case 'relacao':return arr(v).map(id=>(B.rel&&B.rel[id])||'…').join(', ');default:return String(v);}}
function valorHTML(prop,v,linha){if(prop.tipo==='criado_em'||prop.tipo==='atualizado_em')return '<span class="muted">'+esc(valorTexto(prop,v,linha))+'</span>';if(v==null||v===''||(Array.isArray(v)&&!v.length))return '';
  switch(prop.tipo){case 'select':case 'status':{const o=opcaoDe(prop,v);return '<span class="tag '+(o?o.cor:'')+'">'+esc(o?o.nome:v)+'</span>';}
    case 'multi':return arr(v).map(x=>{const o=opcaoDe(prop,x);return '<span class="tag '+(o?o.cor:'')+'">'+esc(o?o.nome:x)+'</span>';}).join('');
    case 'pessoa':return arr(v).map(id=>'<span class="chip"><span class="av" style="width:18px;height:18px;font-size:9px">'+esc((nomeMembro(id)||'?')[0].toUpperCase())+'</span>'+esc(nomeMembro(id)||'?')+'</span>').join('');
    case 'checkbox':return '<span class="chk-box'+(v?' on':'')+'">'+(v?'✓':'')+'</span>';
    case 'url':return '<a href="'+esc(/^https?:/.test(v)?v:'https://'+v)+'" target="_blank" onclick="event.stopPropagation()" style="text-decoration:underline;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%">'+esc(v.replace(/^https?:\/\//,''))+'</a>';
    case 'email':return '<a href="mailto:'+esc(v)+'" onclick="event.stopPropagation()">'+esc(v)+'</a>';
    case 'arquivos':return arr(v).filter(a=>a&&typeof a==='object').map(a=>'<a class="chip" href="'+esc(a.drive_id?arqUrl(a.drive_id,'view'):a.url||'#')+'" target="_blank" onclick="event.stopPropagation()" title="'+esc(a.nome)+'">'+MIME_ICO(a.mime)+' '+esc((a.nome||'arquivo').slice(0,28))+'</a>').join('');
    case 'relacao':return arr(v).map(id=>'<span class="chip" onclick="event.stopPropagation();peek(\''+id+'\')" style="cursor:pointer">↗ '+esc((B.rel&&B.rel[id])||'…')+'</span>').join('');
    case 'data':return '<span>'+esc(valorTexto(prop,v,linha))+'</span>';
    default:return '<span style="white-space:pre-wrap">'+esc(valorTexto(prop,v,linha))+'</span>';}}

// ---------- montar ----------
async function baseMontar(base,host,opts){opts=opts||{};if(!host)return;host.innerHTML='<div class="carregando"><span class="spin"></span></div>';
  base.esquema=base.esquema||baseEsquemaPadrao();base.visoes=(base.visoes&&base.visoes.length)?base.visoes:baseVisoesPadrao();
  const {data:linhas}=await sb.from('hub_paginas').select('id,titulo,icone,props,ordem,criado_em,atualizado_em,atualizado_por,arquivada').eq('base_id',base.id).eq('arquivada',false).order('ordem').order('criado_em');
  const st={host,base,linhas:linhas||[],opts,visaoId:opts.visao||localStorage.getItem('hub_v_'+base.id)||base.visoes[0].id,busca:'',rel:{}};
  if(!base.visoes.some(v=>v.id===st.visaoId))st.visaoId=base.visoes[0].id;
  host._st=st;if(!opts.inline)Object.assign(B,st);
  await baseCarregarRelacoes(st);baseRender(st);}
async function baseCarregarRelacoes(st){const ids=new Set();propsDe(st.base).filter(p=>p.tipo==='relacao').forEach(p=>st.linhas.forEach(l=>arr(l.props[p.id]).forEach(id=>ids.add(id))));if(!ids.size)return;const {data}=await sb.from('hub_paginas').select('id,titulo').in('id',Array.from(ids));(data||[]).forEach(d=>st.rel[d.id]=d.titulo||'Sem título');B.rel=Object.assign(B.rel||{},st.rel);}
function stDe(el){const h=el.closest('.base-wrap');return h&&h.parentElement._st;}
function visaoAtual(st){return st.base.visoes.find(v=>v.id===st.visaoId)||st.base.visoes[0];}
async function baseSalvar(st,patch){const b=st.base;Object.assign(b,patch||{});const {error}=await sb.from('hub_paginas').update({esquema:b.esquema,visoes:b.visoes}).eq('id',b.id);if(error)toast('Erro ao salvar a base: '+error.message,{erro:true});if(S.pagina&&S.pagina.id===b.id){S.pagina.esquema=b.esquema;S.pagina.visoes=b.visoes;}}

function baseRender(st){const v=visaoAtual(st),b=st.base;const pe=podeEditar();
  const tabs=b.visoes.map(x=>'<div class="v'+(x.id===st.visaoId?' active':'')+'" data-v="'+x.id+'"><span class="vi">'+ICO[x.tipo]+'</span>'+esc(x.nome)+'</div>').join('')+(pe?'<div class="v" data-v="__nova" title="Nova visão">+</div>':'');
  const nf=(v.filtros||[]).length;
  st.host.innerHTML='<div class="base-wrap"><div class="base-bar"><div class="views">'+tabs+'</div><div class="base-tools">'+
    '<button class="ic-btn'+(nf?' on':'')+'" data-a="filtro" title="Filtrar">⚲'+(nf?'<sup style="font-size:9px">'+nf+'</sup>':'')+'</button><button class="ic-btn'+((v.ordenar||[]).length?' on':'')+'" data-a="ordenar" title="Ordenar">⇅</button><button class="ic-btn" data-a="busca" title="Buscar na base">⌕</button>'+
    (pe?'<button class="ic-btn" data-a="props" title="Propriedades">≡</button><button class="btn btn-primary btn-sm" data-a="nova" style="margin-left:6px">+ Nova</button>':'')+'</div></div>'+
    '<div class="base-filtros" id="bf_'+b.id+'"></div><div class="base-body"></div></div>';
  const w=$('.base-wrap',st.host);
  $$('.views .v',w).forEach(t=>t.onclick=()=>{if(t.dataset.v==='__nova')return visaoNova(st);if(t.dataset.v===st.visaoId&&pe)return visaoMenu(st,t);st.visaoId=t.dataset.v;localStorage.setItem('hub_v_'+b.id,st.visaoId);st.opts.onVisao&&st.opts.onVisao(st.visaoId);baseRender(st);});
  $$('.views .v',w).forEach(t=>t.oncontextmenu=e=>{e.preventDefault();if(pe&&t.dataset.v!=='__nova'){st.visaoId=t.dataset.v;visaoMenu(st,t);}});
  const bt=a=>$('[data-a='+a+']',w);
  bt('filtro').onclick=e=>filtroMenu(st,e.currentTarget);bt('ordenar').onclick=e=>ordenarMenu(st,e.currentTarget);bt('busca').onclick=e=>{const el=pop(e.currentTarget,'<input class="input sm pin" placeholder="Buscar nesta base…" value="'+esc(st.busca)+'">');$('input',el).oninput=ev=>{st.busca=ev.target.value;baseRenderCorpo(st);};};
  if(pe){bt('props').onclick=e=>propsMenu(st,e.currentTarget);bt('nova').onclick=()=>linhaNova(st,{});}
  baseRenderFiltros(st);baseRenderCorpo(st);}
function baseRenderFiltros(st){const v=visaoAtual(st);const el=$('#bf_'+st.base.id,st.host);if(!el)return;el.innerHTML=(v.filtros||[]).map((f,i)=>{const p=propPorId(st.base,f.prop);return '<span class="fchip on" data-i="'+i+'">'+esc(p?p.nome:'?')+' '+esc(opLabel(f.op))+' <b>'+esc(filtroValorTexto(p,f))+'</b><span class="x">✕</span></span>';}).join('')+(v.agrupar&&v.tipo!=='kanban'?'<span class="fchip">Agrupado por '+esc((propPorId(st.base,v.agrupar)||{}).nome||'?')+'<span class="x" data-g="1">✕</span></span>':'');
  $$('.fchip[data-i]',el).forEach(c=>{c.onclick=e=>{if(e.target.classList.contains('x')){v.filtros.splice(+c.dataset.i,1);baseSalvar(st);baseRender(st);}else filtroEditar(st,c,v.filtros[+c.dataset.i]);};});
  const g=$('[data-g]',el);if(g)g.onclick=()=>{v.agrupar=null;baseSalvar(st);baseRender(st);};}
const OPS={texto:[['contem','contém'],['nao_contem','não contém'],['igual','é'],['vazio','está vazio'],['nao_vazio','não está vazio']],select:[['igual','é'],['diferente','não é'],['vazio','está vazio'],['nao_vazio','não está vazio']],multi:[['contem','contém'],['nao_contem','não contém'],['vazio','está vazio'],['nao_vazio','não está vazio']],numero:[['igual','='],['maior','>'],['menor','<'],['vazio','está vazio'],['nao_vazio','não está vazio']],data:[['igual','é'],['antes','antes de'],['depois','depois de'],['hoje','é hoje'],['semana','esta semana'],['atrasada','já passou'],['vazio','está vazio'],['nao_vazio','não está vazio']],checkbox:[['marcado','marcado'],['desmarcado','desmarcado']],pessoa:[['contem','contém'],['eu','sou eu'],['vazio','está vazio'],['nao_vazio','não está vazio']]};
function opsDe(p){return OPS[p.tipo]||OPS[p.tipo==='status'?'select':p.tipo==='url'||p.tipo==='email'||p.tipo==='telefone'||p.tipo==='relacao'||p.tipo==='arquivos'?'texto':'texto']||OPS.texto;}
function opLabel(op){for(const k in OPS){const f=OPS[k].find(o=>o[0]===op);if(f)return f[1];}return op;}
function filtroValorTexto(p,f){if(!p||['vazio','nao_vazio','hoje','semana','atrasada','marcado','desmarcado','eu'].includes(f.op))return '';if(p.tipo==='select'||p.tipo==='status'||p.tipo==='multi'){const o=opcaoDe(p,f.valor);return o?o.nome:String(f.valor||'');}if(p.tipo==='pessoa')return nomeMembro(f.valor)||'';if(p.tipo==='data')return fmtData(f.valor);return String(f.valor==null?'':f.valor);}
function filtroMenu(st,anchor){const v=visaoAtual(st);const props=propsDe(st.base).filter(p=>!['arquivos','criado_em','atualizado_em'].includes(p.tipo));menu(anchor,[{lbl:'Filtrar por'}].concat(props.map(p=>({t:p.nome,ico:ICO[p.tipo],f:()=>{v.filtros=v.filtros||[];const f={prop:p.id,op:opsDe(p)[0][0],valor:null};v.filtros.push(f);baseRenderFiltros(st);const chip=$$('#bf_'+st.base.id+' .fchip[data-i]',st.host).pop();filtroEditar(st,chip||anchor,f);}}))));}
function filtroEditar(st,anchor,f){const v=visaoAtual(st);const p=propPorId(st.base,f.prop);if(!p)return;const ops=opsDe(p);
  let html='<div class="plbl">'+esc(p.nome).toUpperCase()+'</div><select class="input sm pin" id="fo">'+ops.map(o=>'<option value="'+o[0]+'"'+(o[0]===f.op?' selected':'')+'>'+esc(o[1])+'</option>').join('')+'</select><div id="fv"></div><div class="psep"></div><div class="pi" id="fdel"><span class="ico">✕</span><span>Remover filtro</span></div>';
  const el=pop(anchor,html,{semFoco:true});const fv=$('#fv',el);
  const renderV=()=>{const semValor=['vazio','nao_vazio','hoje','semana','atrasada','marcado','desmarcado','eu'].includes(f.op);fv.innerHTML='';if(semValor)return;
    if(p.tipo==='select'||p.tipo==='status'||p.tipo==='multi')fv.innerHTML='<select class="input sm pin" id="fval"><option value="">—</option>'+(p.opcoes||[]).map(o=>'<option value="'+esc(o.id)+'"'+(o.id===f.valor?' selected':'')+'>'+esc(o.nome)+'</option>').join('')+'</select>';
    else if(p.tipo==='pessoa')fv.innerHTML='<select class="input sm pin" id="fval"><option value="">—</option>'+S.membros.map(m=>'<option value="'+m.user_id+'"'+(m.user_id===f.valor?' selected':'')+'>'+esc(m.nome||m.email)+'</option>').join('')+'</select>';
    else if(p.tipo==='data')fv.innerHTML='<input type="date" class="input sm pin" id="fval" value="'+esc(f.valor||'')+'">';
    else if(p.tipo==='numero')fv.innerHTML='<input type="number" class="input sm pin" id="fval" value="'+esc(f.valor==null?'':f.valor)+'">';
    else fv.innerHTML='<input class="input sm pin" id="fval" value="'+esc(f.valor||'')+'" placeholder="valor">';
    const i=$('#fval',fv);if(i){i.oninput=()=>{f.valor=i.value;baseRenderCorpo(st);baseRenderFiltros(st);};i.focus();}};
  $('#fo',el).onchange=e=>{f.op=e.target.value;renderV();baseRenderCorpo(st);baseRenderFiltros(st);};renderV();
  $('#fdel',el).onclick=()=>{popFechar();v.filtros=v.filtros.filter(x=>x!==f);baseSalvar(st);baseRender(st);};
  const antes=POP;const salvarAoFechar=()=>{baseSalvar(st);};POP.el.addEventListener('DOMNodeRemoved',()=>{},{once:true});const obs=new MutationObserver(()=>{if(!document.body.contains(el)){salvarAoFechar();obs.disconnect();}});obs.observe(document.body,{childList:true});}
function ordenarMenu(st,anchor){const v=visaoAtual(st);const props=[{id:'__titulo',nome:'Título',tipo:'titulo'}].concat(propsDe(st.base));const cur=(v.ordenar||[])[0];
  const html='<div class="plbl">ORDENAR POR</div>'+props.map(p=>'<div class="pi" data-p="'+p.id+'"><span class="ico">'+ICO[p.tipo]+'</span><span>'+esc(p.nome)+'</span>'+(cur&&cur.prop===p.id?'<span class="sub">'+(cur.dir==='desc'?'↓':'↑')+'</span>':'')+'</div>').join('')+(cur?'<div class="psep"></div><div class="pi" data-p="__rm"><span class="ico">✕</span><span>Remover ordenação</span></div>':'');
  const el=pop(anchor,html);$$('.pi',el).forEach(d=>d.onclick=()=>{popFechar();if(d.dataset.p==='__rm'){v.ordenar=[];}else if(cur&&cur.prop===d.dataset.p)v.ordenar=[{prop:d.dataset.p,dir:cur.dir==='asc'?'desc':'asc'}];else v.ordenar=[{prop:d.dataset.p,dir:'asc'}];baseSalvar(st);baseRender(st);});}

// ---------- filtrar / ordenar / agrupar ----------
function linhaPassaFiltro(st,l,f){const p=propPorId(st.base,f.prop);if(!p)return true;let v=l.props[p.id];const vazio=v==null||v===''||(Array.isArray(v)&&!v.length);
  switch(f.op){case 'vazio':return vazio;case 'nao_vazio':return !vazio;case 'marcado':return !!v;case 'desmarcado':return !v;case 'eu':return Array.isArray(v)&&v.includes(S.me.id);
    case 'igual':if(p.tipo==='data'){const d=typeof v==='object'&&v?v.inicio:v;return (d||'').slice(0,10)===(f.valor||'');}if(p.tipo==='numero')return +v===+f.valor;return (p.tipo==='select'||p.tipo==='status')?(v===f.valor||(opcaoDe(p,v)||{}).id===f.valor):String(v||'').toLowerCase()===String(f.valor||'').toLowerCase();
    case 'diferente':return !(v===f.valor||(opcaoDe(p,v)||{}).id===f.valor);
    case 'contem':if(Array.isArray(v))return v.some(x=>x===f.valor||(opcaoDe(p,x)||{}).id===f.valor||String(x).toLowerCase().includes(String(f.valor||'').toLowerCase()));return String(valorTexto(p,v,l)).toLowerCase().includes(String(f.valor||'').toLowerCase());
    case 'nao_contem':if(Array.isArray(v))return !v.some(x=>x===f.valor||(opcaoDe(p,x)||{}).id===f.valor);return !String(valorTexto(p,v,l)).toLowerCase().includes(String(f.valor||'').toLowerCase());
    case 'maior':return +v>+f.valor;case 'menor':return +v<+f.valor;
    case 'antes':{const d=(typeof v==='object'&&v?v.inicio:v)||'';return !!d&&d.slice(0,10)<(f.valor||'');}case 'depois':{const d=(typeof v==='object'&&v?v.inicio:v)||'';return !!d&&d.slice(0,10)>(f.valor||'');}
    case 'hoje':{const d=(typeof v==='object'&&v?v.inicio:v)||'';return d.slice(0,10)===hoje();}
    case 'semana':{const d=(typeof v==='object'&&v?v.inicio:v)||'';if(!d)return false;const t=new Date(d.slice(0,10)+'T12:00:00'),n=new Date();const ini=new Date(n);ini.setDate(n.getDate()-n.getDay());ini.setHours(0,0,0,0);const fim=new Date(ini);fim.setDate(ini.getDate()+7);return t>=ini&&t<fim;}
    case 'atrasada':{const d=(typeof v==='object'&&v?v.inicio:v)||'';return !!d&&d.slice(0,10)<hoje();}}
  return true;}
function linhasVisiveis(st){const v=visaoAtual(st);let ls=st.linhas.slice();(v.filtros||[]).forEach(f=>{ls=ls.filter(l=>linhaPassaFiltro(st,l,f));});
  if(st.busca){const q=st.busca.toLowerCase();ls=ls.filter(l=>(l.titulo||'').toLowerCase().includes(q)||propsDe(st.base).some(p=>valorTexto(p,l.props[p.id],l).toLowerCase().includes(q)));}
  const ord=(v.ordenar||[])[0];if(ord){const p=ord.prop==='__titulo'?{id:'__titulo',tipo:'titulo'}:propPorId(st.base,ord.prop);if(p){const key=l=>{if(p.id==='__titulo')return (l.titulo||'').toLowerCase();const x=l.props[p.id];if(p.tipo==='numero')return +x||0;if(p.tipo==='data')return (typeof x==='object'&&x?x.inicio:x)||'';if(p.tipo==='checkbox')return x?1:0;if(p.tipo==='select'||p.tipo==='status'){const i=(p.opcoes||[]).findIndex(o=>o.id===x||o.nome===x);return i<0?999:i;}if(p.tipo==='criado_em')return l.criado_em;if(p.tipo==='atualizado_em')return l.atualizado_em;return valorTexto(p,x,l).toLowerCase();};ls.sort((a,b)=>{const ka=key(a),kb=key(b);return (ka<kb?-1:ka>kb?1:0)*(ord.dir==='desc'?-1:1);});}}
  return ls;}
function gruposDe(st,ls,propId){const p=propPorId(st.base,propId);if(!p)return [{id:null,nome:'Tudo',linhas:ls}];
  if(p.tipo==='select'||p.tipo==='status'){const gs=(p.opcoes||[]).map(o=>({id:o.id,nome:o.nome,cor:o.cor,linhas:ls.filter(l=>l.props[p.id]===o.id||l.props[p.id]===o.nome)}));gs.unshift({id:'',nome:'Sem '+p.nome.toLowerCase(),cor:'',linhas:ls.filter(l=>{const v=l.props[p.id];return v==null||v===''||!(p.opcoes||[]).some(o=>o.id===v||o.nome===v);})});return gs;}
  if(p.tipo==='pessoa'){const gs=S.membros.map(m=>({id:m.user_id,nome:m.nome||m.email,linhas:ls.filter(l=>arr(l.props[p.id]).includes(m.user_id))}));gs.unshift({id:'',nome:'Sem responsável',linhas:ls.filter(l=>!arr(l.props[p.id]).length)});return gs;}
  if(p.tipo==='checkbox')return [{id:'1',nome:'Marcado',linhas:ls.filter(l=>l.props[p.id])},{id:'',nome:'Desmarcado',linhas:ls.filter(l=>!l.props[p.id])}];
  const m={};ls.forEach(l=>{const k=valorTexto(p,l.props[p.id],l)||'(vazio)';(m[k]=m[k]||[]).push(l);});return Object.keys(m).sort().map(k=>({id:k,nome:k,linhas:m[k]}));}

// ---------- corpo ----------
function baseRenderCorpo(st){const v=visaoAtual(st);const body=$('.base-body',st.host);const ls=linhasVisiveis(st);
  const f={tabela:renderTabela,kanban:renderKanban,lista:renderLista,galeria:renderGaleria,calendario:renderCalendario}[v.tipo]||renderTabela;f(st,body,ls,v);}
function propsVisiveis(st,v){const all=propsDe(st.base);if(!v.props)return all;return v.props.map(id=>all.find(p=>p.id===id)).filter(Boolean);}
function tituloHTML(l){return '<span class="ti">'+iconeDe(l)+'</span><span>'+esc(l.titulo||'Sem título')+'</span>';}

function renderTabela(st,body,ls,v){const props=propsVisiveis(st,v);const pe=podeEditar();
  const head='<tr><th data-p="__titulo"><span class="thi"><span class="pt-ico">Aa</span>Nome</span></th>'+props.map(p=>'<th data-p="'+p.id+'"><span class="thi"><span class="pt-ico">'+ICO[p.tipo]+'</span>'+esc(p.nome)+'</span></th>').join('')+(pe?'<th class="add" data-p="__add" title="Nova propriedade">+</th>':'')+'</tr>';
  const linha=l=>'<tr data-id="'+l.id+'"><td><div class="cell titulo" data-p="__titulo">'+tituloHTML(l)+'<button class="open-btn">Abrir</button></div></td>'+props.map(p=>'<td><div class="cell'+(p.tipo==='numero'?' num':p.tipo==='checkbox'?' chk':'')+'" data-p="'+p.id+'">'+valorHTML(p,l.props[p.id],l)+'</div></td>').join('')+(pe?'<td></td>':'')+'</tr>';
  let corpo='';const nCols=props.length+1+(pe?1:0);
  if(v.agrupar){gruposDe(st,ls,v.agrupar).forEach(g=>{if(!g.linhas.length&&v.esconderVazios!==false)return;corpo+='<tr class="grp-head"><td colspan="'+nCols+'"><span class="tag '+(g.cor||'')+'">'+esc(g.nome)+'</span><span class="n">'+g.linhas.length+'</span></td></tr>'+g.linhas.map(linha).join('');});}
  else corpo=ls.map(linha).join('');
  body.innerHTML='<div class="tbl-wrap"><table class="tbl"><thead>'+head+'</thead><tbody>'+corpo+(pe?'<tr class="nova-linha"><td colspan="'+nCols+'"><div class="cell" data-nova="1">+ Nova</div></td></tr>':'')+'<tr class="cnt"><td colspan="'+nCols+'">'+ls.length+' '+(ls.length===1?'item':'itens')+'</td></tr></tbody></table></div>';
  ligarCelulas(st,body);
  $$('th[data-p]',body).forEach(th=>th.onclick=()=>{if(th.dataset.p==='__add')return propNova(st,th);colunaMenu(st,th,th.dataset.p);});
  const nv=$('[data-nova]',body);if(nv)nv.onclick=()=>linhaNova(st,{});}
function ligarCelulas(st,body){$$('.cell[data-p]',body).forEach(c=>{const tr=c.closest('tr');const l=st.linhas.find(x=>x.id===tr.dataset.id);if(!l)return;const pid=c.dataset.p;
  if(pid==='__titulo'){$('.open-btn',c).onclick=e=>{e.stopPropagation();peek(l.id);};c.onclick=e=>{if(!podeEditar())return peek(l.id);celulaTitulo(st,c,l);};return;}
  const p=propPorId(st.base,pid);if(!p)return;c.onclick=e=>{if(!podeEditar())return;celulaEditar(st,c,l,p);};});}
function celulaTitulo(st,c,l){if(c.classList.contains('editing'))return;c.classList.add('editing');c.innerHTML='<input class="input sm" value="'+esc(l.titulo||'')+'" style="flex:1">';const i=$('input',c);i.focus();i.select();
  const fim=async()=>{const v=i.value.trim();c.classList.remove('editing');l.titulo=v;c.innerHTML=tituloHTML(l)+'<button class="open-btn">Abrir</button>';$('.open-btn',c).onclick=e=>{e.stopPropagation();peek(l.id);};await sb.from('hub_paginas').update({titulo:v}).eq('id',l.id);};
  i.onblur=fim;i.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();i.blur();}if(e.key==='Escape'){i.value=l.titulo||'';i.blur();}};}
async function linhaSet(st,l,pid,valor){l.props=l.props||{};if(valor==null||valor===''||(Array.isArray(valor)&&!valor.length))delete l.props[pid];else l.props[pid]=valor;const texto=textoPlano({blocks:[]},l.props,st.base.esquema);
  const {error}=await sb.from('hub_paginas').update({props:l.props,texto:texto||undefined}).eq('id',l.id);if(error)toast('Erro ao salvar: '+error.message,{erro:true});
  if(S.pagina&&S.pagina.id===l.id)S.pagina.props=l.props;}
function celulaEditar(st,c,l,p){const v=l.props[p.id];const refaz=()=>{c.innerHTML=valorHTML(p,l.props[p.id],l);baseAtualizarVisaoSeAgrupada(st,p.id);};
  switch(p.tipo){
    case 'checkbox':linhaSet(st,l,p.id,!v);refaz();return;
    case 'select':case 'status':return selectPicker(c,p,v,async nv=>{await linhaSet(st,l,p.id,nv);refaz();},st);
    case 'multi':return multiPicker(c,p,arr(v),async nv=>{await linhaSet(st,l,p.id,nv);refaz();},st);
    case 'pessoa':return pessoaPicker(c,arr(v),async nv=>{await linhaSet(st,l,p.id,nv);refaz();});
    case 'data':return dataPicker(c,v,async nv=>{await linhaSet(st,l,p.id,nv);refaz();});
    case 'arquivos':return arquivosPicker(c,arr(v),l,async nv=>{await linhaSet(st,l,p.id,nv);refaz();});
    case 'relacao':return relacaoPicker(c,p,arr(v),async nv=>{await linhaSet(st,l,p.id,nv);await baseCarregarRelacoes(st);refaz();});
    case 'criado_em':case 'atualizado_em':return;
    default:{if(c.classList.contains('editing'))return;c.classList.add('editing');const multi=p.tipo==='texto';c.innerHTML=multi?'<textarea class="input sm" style="min-height:60px;width:100%">'+esc(v==null?'':v)+'</textarea>':'<input class="input sm" type="'+(p.tipo==='numero'?'number':'text')+'" value="'+esc(v==null?'':v)+'" style="width:100%">';const i=$('input,textarea',c);i.focus();
      const fim=async()=>{let nv=i.value;if(p.tipo==='numero')nv=nv===''?null:+nv;c.classList.remove('editing');await linhaSet(st,l,p.id,nv);refaz();};i.onblur=fim;i.onkeydown=e=>{if(e.key==='Enter'&&!(multi&&e.shiftKey)){e.preventDefault();i.blur();}if(e.key==='Escape'){i.value=v==null?'':v;i.blur();}};}}}
function baseAtualizarVisaoSeAgrupada(st,pid){const v=visaoAtual(st);if(v.tipo==='kanban'||(v.agrupar===pid)||(v.ordenar||[]).some(o=>o.prop===pid)||(v.filtros||[]).some(f=>f.prop===pid))baseRenderCorpo(st);}

// ---------- pickers ----------
function selectPicker(anchor,p,v,cb,st){let q='';const render=()=>{const ops=(p.opcoes||[]).filter(o=>!q||o.nome.toLowerCase().includes(q.toLowerCase()));let html='<input class="input sm pin" placeholder="Buscar ou criar…" value="'+esc(q)+'">'+ops.map(o=>'<div class="pi" data-id="'+esc(o.id)+'"><span class="tag '+o.cor+'">'+esc(o.nome)+'</span>'+(o.id===v||o.nome===v?'<span class="sub">✓</span>':'')+'</div>').join('')+(q&&!ops.some(o=>o.nome.toLowerCase()===q.toLowerCase())&&podeEditar()?'<div class="pi" data-novo="1"><span class="ico">+</span><span>Criar "'+esc(q)+'"</span></div>':'')+(v?'<div class="psep"></div><div class="pi" data-limpar="1"><span class="ico">✕</span><span>Limpar</span></div>':'');
    const el=pop(anchor,html,{manter:true});const i=$('input',el);i.focus();i.setSelectionRange(q.length,q.length);i.oninput=()=>{q=i.value;render();};i.onkeydown=e=>{if(e.key==='Enter'){const f=$('.pi',el);f&&f.click();}};
    $$('.pi',el).forEach(d=>d.onclick=async()=>{popFechar();if(d.dataset.limpar)return cb(null);if(d.dataset.novo){const o={id:sid(),nome:q.trim(),cor:corAleatoria()};p.opcoes=(p.opcoes||[]).concat([o]);await baseSalvar(st);return cb(o.id);}cb(d.dataset.id);});};render();}
function multiPicker(anchor,p,v,cb,st){let q='',sel=v.slice();const render=()=>{const ops=(p.opcoes||[]).filter(o=>!q||o.nome.toLowerCase().includes(q.toLowerCase()));let html='<div class="ptags">'+sel.map(id=>{const o=opcaoDe(p,id);return '<span class="tag '+(o?o.cor:'')+'" data-rm="'+esc(id)+'">'+esc(o?o.nome:id)+' ✕</span>';}).join('')+'</div><input class="input sm pin" placeholder="Buscar ou criar…" value="'+esc(q)+'">'+ops.map(o=>'<div class="pi" data-id="'+esc(o.id)+'"><span class="tag '+o.cor+'">'+esc(o.nome)+'</span>'+(sel.includes(o.id)?'<span class="sub">✓</span>':'')+'</div>').join('')+(q&&!ops.some(o=>o.nome.toLowerCase()===q.toLowerCase())&&podeEditar()?'<div class="pi" data-novo="1"><span class="ico">+</span><span>Criar "'+esc(q)+'"</span></div>':'');
    const el=pop(anchor,html,{manter:true,onFechar:()=>cb(sel)});const i=$('input',el);i.focus();i.oninput=()=>{q=i.value;render();};
    $$('.tag[data-rm]',el).forEach(t=>t.onclick=()=>{sel=sel.filter(x=>x!==t.dataset.rm);render();});
    $$('.pi',el).forEach(d=>d.onclick=async()=>{if(d.dataset.novo){const o={id:sid(),nome:q.trim(),cor:corAleatoria()};p.opcoes=(p.opcoes||[]).concat([o]);await baseSalvar(st);sel.push(o.id);q='';}else{const id=d.dataset.id;sel=sel.includes(id)?sel.filter(x=>x!==id):sel.concat([id]);}render();});};render();}
function pessoaPicker(anchor,v,cb){let sel=v.slice();const render=()=>{const html='<div class="plbl">PESSOAS</div>'+S.membros.map(m=>'<div class="pi" data-id="'+m.user_id+'"><span class="av" style="width:22px;height:22px;font-size:10px">'+esc((m.nome||m.email)[0].toUpperCase())+'</span><span>'+esc(m.nome||m.email)+'</span>'+(sel.includes(m.user_id)?'<span class="sub">✓</span>':'')+'</div>').join('')+(sel.length?'<div class="psep"></div><div class="pi" data-limpar="1"><span class="ico">✕</span><span>Limpar</span></div>':'');
    const el=pop(anchor,html,{manter:true,onFechar:()=>cb(sel)});$$('.pi',el).forEach(d=>d.onclick=()=>{if(d.dataset.limpar){sel=[];}else{const id=d.dataset.id;sel=sel.includes(id)?sel.filter(x=>x!==id):sel.concat([id]);}render();});};render();}
function dataPicker(anchor,v,cb){const d=(typeof v==='object'&&v)?v:{inicio:v||'',fim:'',hora:false};const html='<div class="plbl">DATA</div><input type="'+(d.hora?'datetime-local':'date')+'" class="input sm pin" id="d_i" value="'+esc(d.inicio||'')+'"><label class="pi" style="font-size:13px"><input type="checkbox" id="d_f" '+(d.fim?'checked':'')+'> Data final</label><input type="'+(d.hora?'datetime-local':'date')+'" class="input sm pin" id="d_fv" value="'+esc(d.fim||'')+'" style="display:'+(d.fim?'block':'none')+'"><label class="pi" style="font-size:13px"><input type="checkbox" id="d_h" '+(d.hora?'checked':'')+'> Incluir hora</label><div class="psep"></div><div class="pi" id="d_hoje"><span class="ico">●</span><span>Hoje</span></div><div class="pi" id="d_rm"><span class="ico">✕</span><span>Limpar</span></div>';
  const el=pop(anchor,html,{manter:true,onFechar:()=>{const i=$('#d_i',el).value,f=$('#d_f',el).checked?$('#d_fv',el).value:'';cb(i?{inicio:i,fim:f||'',hora:$('#d_h',el).checked}:null);}});
  $('#d_f',el).onchange=e=>{$('#d_fv',el).style.display=e.target.checked?'block':'none';};$('#d_h',el).onchange=e=>{const t=e.target.checked?'datetime-local':'date';['d_i','d_fv'].forEach(id=>{const x=$('#'+id,el);const val=x.value;x.type=t;x.value=val.length>10&&!e.target.checked?val.slice(0,10):val;});};
  $('#d_hoje',el).onclick=()=>{popFechar();cb({inicio:hoje(),fim:'',hora:false});};$('#d_rm',el).onclick=()=>{popFechar();cb(null);};}
function arquivosPicker(anchor,v,l,cb){const html='<div class="plbl">ARQUIVOS</div>'+(v.map((a,i)=>'<div class="pi"><span class="ico">'+MIME_ICO(a.mime)+'</span><span style="overflow:hidden;text-overflow:ellipsis">'+esc(a.nome)+'</span><span class="sub" data-rm="'+i+'" style="cursor:pointer">✕</span></div>').join('')||'<div class="pi soft">Nenhum arquivo</div>')+'<div class="psep"></div><div class="pi" id="af_up"><span class="ico">⇧</span><span>Enviar arquivo (Drive)</span></div>';
  const el=pop(anchor,html,{manter:true});$$('[data-rm]',el).forEach(x=>x.onclick=()=>{popFechar();cb(v.filter((_,i)=>i!==+x.dataset.rm));});
  $('#af_up',el).onclick=()=>{popFechar();escolherArquivos(async fs=>{const out=v.slice();for(const f of fs){const a=await uploadArquivo(f,l.id);if(a)out.push({drive_id:a.drive_id,nome:a.nome,mime:a.mime,tamanho:a.tamanho,link:a.link});}cb(out);},'',true);};}
async function relacaoPicker(anchor,p,v,cb){let q='',sel=v.slice();const base=p.base||null;let todas=[];if(base){const {data}=await sb.from('hub_paginas').select('id,titulo,icone').eq('base_id',base).eq('arquivada',false).order('titulo');todas=data||[];}else{todas=S.tree.filter(x=>!x.arquivada);}
  const render=()=>{const ops=todas.filter(o=>!q||(o.titulo||'').toLowerCase().includes(q.toLowerCase())).slice(0,40);const html='<div class="ptags">'+sel.map(id=>'<span class="chip" data-rm="'+id+'">'+esc((todas.find(t=>t.id===id)||{}).titulo||B.rel[id]||'…')+' ✕</span>').join('')+'</div><input class="input sm pin" placeholder="Buscar…" value="'+esc(q)+'">'+ops.map(o=>'<div class="pi" data-id="'+o.id+'"><span class="ico">'+iconeDe(o)+'</span><span>'+esc(o.titulo||'Sem título')+'</span>'+(sel.includes(o.id)?'<span class="sub">✓</span>':'')+'</div>').join('');
    const el=pop(anchor,html,{manter:true,onFechar:()=>cb(sel)});const i=$('input',el);i.focus();i.oninput=()=>{q=i.value;render();};$$('.chip[data-rm]',el).forEach(t=>t.onclick=()=>{sel=sel.filter(x=>x!==t.dataset.rm);render();});$$('.pi',el).forEach(d=>d.onclick=()=>{const id=d.dataset.id;sel=sel.includes(id)?sel.filter(x=>x!==id):sel.concat([id]);render();});};render();}

// ---------- linhas ----------
async function linhaNova(st,props,abrir){if(!podeEditar())return;const v=visaoAtual(st);const ordem=st.linhas.length?Math.max(...st.linhas.map(l=>l.ordem||0))+1:1;
  const {data,error}=await sb.from('hub_paginas').insert({parent_id:st.base.id,base_id:st.base.id,tipo:'pagina',titulo:'',props:props||{},ordem}).select().single();if(error)return toast('Erro: '+error.message,{erro:true});
  st.linhas.push(data);baseRenderCorpo(st);
  if(abrir||v.tipo!=='tabela')peek(data.id);else{const c=$('.cell.titulo[data-p=__titulo]',$('tr[data-id="'+data.id+'"]',st.host));if(c)celulaTitulo(st,c,data);}}
async function linhaExcluir(st,l){if(!await confirmar('Arquivar item','"'+(l.titulo||'Sem título')+'" vai para a lixeira.'))return;await sb.from('hub_paginas').update({arquivada:true}).eq('id',l.id);st.linhas=st.linhas.filter(x=>x.id!==l.id);baseRenderCorpo(st);}
function baseAtualizarLinha(id){$$('.base-wrap').forEach(async w=>{const st=w.parentElement._st;if(!st)return;const {data}=await sb.from('hub_paginas').select('id,titulo,icone,props,ordem,criado_em,atualizado_em,atualizado_por,arquivada').eq('id',id).maybeSingle();if(!data)return;const i=st.linhas.findIndex(l=>l.id===id);if(data.arquivada){if(i>=0)st.linhas.splice(i,1);}else if(i>=0)st.linhas[i]=data;else if(data.base_id===st.base.id)st.linhas.push(data);baseRenderCorpo(st);});}
function baseLinhaRealtime(n,ev){$$('.base-wrap').forEach(w=>{const st=w.parentElement._st;if(!st||st.base.id!==n.base_id)return;if(n.atualizado_por===S.me.id&&ev!=='DELETE')return;const i=st.linhas.findIndex(l=>l.id===n.id);if(n.arquivada){if(i>=0)st.linhas.splice(i,1);}else if(i>=0)st.linhas[i]=Object.assign(st.linhas[i],n);else st.linhas.push(n);baseRenderCorpo(st);});}
function baseRecarregar(baseId){$$('.base-wrap').forEach(w=>{const st=w.parentElement._st;if(st&&st.base.id===baseId)baseMontar(st.base,st.host,st.opts);});}
function linhaMenu(st,anchor,l){menu(anchor,[{t:'Abrir',ico:'↗',f:()=>peek(l.id)},{t:'Abrir como página',ico:'📄',f:()=>abrirPagina(l.id)},{t:'Copiar link',ico:'🔗',f:()=>copiar(linkPagina(l.id),'Link copiado')},'-',{t:'Duplicar',ico:'⧉',f:async()=>{const {data}=await sb.from('hub_paginas').select('*').eq('id',l.id).single();const {data:n}=await sb.from('hub_paginas').insert({parent_id:st.base.id,base_id:st.base.id,tipo:'pagina',titulo:(data.titulo||'')+' (cópia)',icone:data.icone,conteudo:data.conteudo,props:data.props,ordem:(l.ordem||0)+.5}).select().single();if(n){st.linhas.push(n);baseRenderCorpo(st);}}},{t:'Arquivar',ico:'🗑',danger:true,f:()=>linhaExcluir(st,l)}]);}

// ---------- kanban ----------
function renderKanban(st,body,ls,v){const pid=v.agrupar||(propsDe(st.base).find(p=>p.tipo==='status'||p.tipo==='select')||{}).id;if(!pid){body.innerHTML='<div class="vazio-box">Crie uma propriedade de Seleção ou Status para usar o kanban.</div>';return;}
  const p=propPorId(st.base,pid);const props=propsVisiveis(st,v).filter(x=>x.id!==pid);const gs=gruposDe(st,ls,pid);const pe=podeEditar();
  body.innerHTML='<div class="kanban">'+gs.map(g=>'<div class="kcol" data-g="'+esc(g.id)+'"><div class="kcol-h">'+(g.cor!=null?'<span class="tag '+g.cor+'">'+esc(g.nome)+'</span>':'<span>'+esc(g.nome)+'</span>')+'<span class="n">'+g.linhas.length+'</span>'+(pe?'<button class="ic-btn" title="Nova">+</button>':'')+'</div>'+g.linhas.map(l=>'<div class="kcard" draggable="'+pe+'" data-id="'+l.id+'"><div class="kt">'+tituloHTML(l)+'</div><div class="kp">'+props.map(x=>{const h=valorHTML(x,l.props[x.id],l);return h?'<span>'+h+'</span>':'';}).join('')+'</div></div>').join('')+(pe?'<button class="kadd">+ Nova</button>':'')+'</div>').join('')+'</div>';
  $$('.kcard',body).forEach(c=>{c.onclick=()=>peek(c.dataset.id);c.oncontextmenu=e=>{e.preventDefault();linhaMenu(st,c,st.linhas.find(l=>l.id===c.dataset.id));};
    c.ondragstart=e=>{e.dataTransfer.setData('text/plain',c.dataset.id);c.classList.add('drag');};c.ondragend=()=>c.classList.remove('drag');});
  $$('.kcol',body).forEach(col=>{const nova=()=>linhaNova(st,col.dataset.g?{[pid]:p.tipo==='pessoa'?[col.dataset.g]:p.tipo==='checkbox'?!!col.dataset.g:col.dataset.g}:{},true);$$('.kadd,.kcol-h .ic-btn',col).forEach(b=>b.onclick=nova);
    col.ondragover=e=>{e.preventDefault();col.classList.add('over');};col.ondragleave=()=>col.classList.remove('over');col.ondrop=async e=>{e.preventDefault();col.classList.remove('over');const id=e.dataTransfer.getData('text/plain');const l=st.linhas.find(x=>x.id===id);if(!l)return;const g=col.dataset.g;let nv=g||null;if(p.tipo==='pessoa')nv=g?[g]:[];if(p.tipo==='checkbox')nv=!!g;await linhaSet(st,l,pid,nv);baseRenderCorpo(st);};});}
// ---------- lista ----------
function renderLista(st,body,ls,v){const props=propsVisiveis(st,v);const grupos=v.agrupar?gruposDe(st,ls,v.agrupar).filter(g=>g.linhas.length):[{linhas:ls}];
  body.innerHTML='<div class="lista">'+grupos.map(g=>(g.nome?'<div class="grp-head" style="padding:10px 10px 4px;font-weight:600;font-size:13px"><span class="tag '+(g.cor||'')+'">'+esc(g.nome)+'</span> <span class="n soft">'+g.linhas.length+'</span></div>':'')+g.linhas.map(l=>'<div class="li" data-id="'+l.id+'"><div class="lt">'+tituloHTML(l)+'</div><div class="lp">'+props.map(x=>valorHTML(x,l.props[x.id],l)).filter(Boolean).join('')+'</div></div>').join('')).join('')+(podeEditar()?'<button class="kadd">+ Nova</button>':'')+(ls.length?'':'<div class="vazio-box">Nada aqui ainda.</div>')+'</div>';
  $$('.li',body).forEach(d=>{d.onclick=()=>peek(d.dataset.id);d.oncontextmenu=e=>{e.preventDefault();linhaMenu(st,d,st.linhas.find(l=>l.id===d.dataset.id));};});const a=$('.kadd',body);if(a)a.onclick=()=>linhaNova(st,{},true);}
// ---------- galeria ----------
function renderGaleria(st,body,ls,v){const props=propsVisiveis(st,v);const capa=l=>{const af=propsDe(st.base).find(p=>p.tipo==='arquivos');const a=af&&(l.props[af.id]||[]).find(x=>(x.mime||'').startsWith('image/'));if(a&&a.drive_id)return 'background-image:url('+arqUrl(a.drive_id,'thumb','w600')+')';return '';};
  body.innerHTML='<div class="galeria">'+ls.map(l=>'<div class="gcard" data-id="'+l.id+'"><div class="gc-cover" style="'+capa(l)+'">'+(capa(l)?'':iconeDe(l))+'</div><div class="gc-body"><div class="gt">'+esc(l.titulo||'Sem título')+'</div><div class="gp">'+props.map(x=>valorHTML(x,l.props[x.id],l)).filter(Boolean).join('')+'</div></div></div>').join('')+(podeEditar()?'<div class="gcard" id="g_nova" style="display:flex;align-items:center;justify-content:center;color:var(--soft);min-height:120px;border-style:dashed">+ Nova</div>':'')+'</div>';
  $$('.gcard[data-id]',body).forEach(d=>{d.onclick=()=>peek(d.dataset.id);d.oncontextmenu=e=>{e.preventDefault();linhaMenu(st,d,st.linhas.find(l=>l.id===d.dataset.id));};});const n=$('#g_nova',body);if(n)n.onclick=()=>linhaNova(st,{},true);}
// ---------- calendário ----------
function renderCalendario(st,body,ls,v){const pid=v.calendarioPor||(propsDe(st.base).find(p=>p.tipo==='data')||{}).id;if(!pid){body.innerHTML='<div class="vazio-box">Crie uma propriedade de Data para usar o calendário.</div>';return;}
  st.mes=st.mes||(()=>{const d=new Date();return {y:d.getFullYear(),m:d.getMonth()};})();const {y,m}=st.mes;const ini=new Date(y,m,1),fim=new Date(y,m+1,0);const pad=ini.getDay();const dias=[];for(let i=pad-1;i>=0;i--){const d=new Date(y,m,-i);dias.push({d,fora:true});}for(let i=1;i<=fim.getDate();i++)dias.push({d:new Date(y,m,i)});while(dias.length%7)dias.push({d:new Date(y,m+1,dias.length-pad-fim.getDate()+1),fora:true});
  const key=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');const porDia={};ls.forEach(l=>{const x=l.props[pid];const a=(typeof x==='object'&&x?x.inicio:x)||'';if(!a)return;const b=(typeof x==='object'&&x&&x.fim)||a;let d=new Date(a.slice(0,10)+'T12:00:00');const df=new Date(b.slice(0,10)+'T12:00:00');let g=0;while(d<=df&&g++<60){(porDia[key(d)]=porDia[key(d)]||[]).push(l);d.setDate(d.getDate()+1);}});
  const meses=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];const hj=hoje();
  body.innerHTML='<div class="cal"><div class="cal-h"><button class="ic-btn" data-m="-1">‹</button><span>'+meses[m]+' '+y+'</span><button class="ic-btn" data-m="1">›</button><button class="btn btn-sm btn-ghost hoje" data-m="0">Hoje</button></div><div class="cal-g">'+['DOM','SEG','TER','QUA','QUI','SEX','SÁB'].map(d=>'<div class="wd">'+d+'</div>').join('')+dias.map(x=>{const k=key(x.d);return '<div class="d'+(x.fora?' fora':'')+(k===hj?' hoje':'')+'" data-d="'+k+'"><span class="dn">'+x.d.getDate()+'</span>'+(podeEditar()?'<button class="ic-btn add">+</button>':'')+(porDia[k]||[]).map(l=>'<span class="ev" data-id="'+l.id+'">'+esc(l.titulo||'Sem título')+'</span>').join('')+'</div>';}).join('')+'</div></div>';
  $$('[data-m]',body).forEach(b=>b.onclick=()=>{const n=+b.dataset.m;if(n===0){const d=new Date();st.mes={y:d.getFullYear(),m:d.getMonth()};}else{const d=new Date(y,m+n,1);st.mes={y:d.getFullYear(),m:d.getMonth()};}baseRenderCorpo(st);});
  $$('.ev',body).forEach(e=>e.onclick=()=>peek(e.dataset.id));$$('.d .add',body).forEach(b=>b.onclick=()=>linhaNova(st,{[pid]:{inicio:b.parentElement.dataset.d,fim:'',hora:false}},true));}

// ---------- propriedades / colunas ----------
function colunaMenu(st,anchor,pid){const v=visaoAtual(st);if(pid==='__titulo')return ordenarMenu(st,anchor);const p=propPorId(st.base,pid);if(!p)return;const pe=podeEditar();
  const itens=[{t:'Ordenar crescente',ico:'↑',f:()=>{v.ordenar=[{prop:pid,dir:'asc'}];baseSalvar(st);baseRender(st);}},{t:'Ordenar decrescente',ico:'↓',f:()=>{v.ordenar=[{prop:pid,dir:'desc'}];baseSalvar(st);baseRender(st);}},{t:'Filtrar',ico:'⚲',f:()=>{v.filtros=v.filtros||[];const f={prop:pid,op:opsDe(p)[0][0],valor:null};v.filtros.push(f);baseRenderFiltros(st);filtroEditar(st,$$('#bf_'+st.base.id+' .fchip[data-i]',st.host).pop()||anchor,f);}}];
  if(['select','status','pessoa','checkbox'].includes(p.tipo))itens.push({t:v.agrupar===pid?'Desagrupar':'Agrupar por esta',ico:'▥',f:()=>{v.agrupar=v.agrupar===pid?null:pid;baseSalvar(st);baseRender(st);}});
  if(pe)itens.push('-',{t:'Editar propriedade',ico:'✎',f:()=>propEditar(st,anchor,p)},{t:'Ocultar nesta visão',ico:'◌',f:()=>{v.props=propsVisiveis(st,v).map(x=>x.id).filter(x=>x!==pid);baseSalvar(st);baseRender(st);}},{t:'Excluir propriedade',ico:'🗑',danger:true,f:async()=>{if(!await confirmar('Excluir propriedade','"'+p.nome+'" some de todas as linhas. Não dá para desfazer.',{danger:true,ok:'Excluir'}))return;st.base.esquema.props=propsDe(st.base).filter(x=>x.id!==pid);st.base.visoes.forEach(x=>{if(x.props)x.props=x.props.filter(i=>i!==pid);if(x.agrupar===pid)x.agrupar=null;});await baseSalvar(st);baseRender(st);}});
  menu(anchor,itens);}
function propNova(st,anchor){const html='<input class="input sm pin" id="pn_n" placeholder="Nome da propriedade"><div class="plbl">TIPO</div>'+TIPOS_PROP.map(t=>'<div class="pi" data-t="'+t[0]+'"><span class="ico">'+ICO[t[0]]+'</span><span>'+t[1]+'</span></div>').join('');
  const el=pop(anchor,html);$$('.pi',el).forEach(d=>d.onclick=async()=>{const nome=$('#pn_n',el).value.trim()||TIPOS_PROP.find(t=>t[0]===d.dataset.t)[1];popFechar();const p={id:sid(),nome,tipo:d.dataset.t};if(['select','multi','status'].includes(p.tipo))p.opcoes=[];if(p.tipo==='relacao'){const b=await escolherBase();if(b)p.base=b;}st.base.esquema.props.push(p);st.base.visoes.forEach(v=>{if(v.props)v.props.push(p.id);});await baseSalvar(st);baseRender(st);});}
function escolherBase(){return new Promise(res=>{const bases=S.tree.filter(x=>x.tipo==='base'&&!x.arquivada);const bg=modal('<div class="modal-h">Relacionar com qual base?</div><div class="modal-b">'+bases.map(b=>'<div class="pi" data-id="'+b.id+'"><span class="ico">'+iconeDe(b)+'</span><span>'+esc(tituloDe(b))+'</span></div>').join('')+'</div>',{onFechar:()=>res(null)});$$('.pi',bg).forEach(d=>d.onclick=()=>{fecharModal(bg);res(d.dataset.id);});});}
function propEditar(st,anchor,p){const html='<input class="input sm pin" id="pe_n" value="'+esc(p.nome)+'"><select class="input sm pin" id="pe_t">'+TIPOS_PROP.map(t=>'<option value="'+t[0]+'"'+(t[0]===p.tipo?' selected':'')+'>'+t[1]+'</option>').join('')+'</select>'+(p.tipo==='numero'?'<select class="input sm pin" id="pe_f"><option value="">Número</option><option value="reais"'+(p.formato==='reais'?' selected':'')+'>R$</option><option value="pct"'+(p.formato==='pct'?' selected':'')+'>%</option></select>':'')+(['select','multi','status'].includes(p.tipo)?'<div class="plbl">OPÇÕES</div><div id="pe_ops"></div><div class="pi" id="pe_add"><span class="ico">+</span><span>Adicionar opção</span></div>':'');
  const el=pop(anchor,html,{onFechar:()=>{baseSalvar(st);baseRender(st);}});
  $('#pe_n',el).oninput=e=>{p.nome=e.target.value;};$('#pe_t',el).onchange=e=>{p.tipo=e.target.value;if(['select','multi','status'].includes(p.tipo)&&!p.opcoes)p.opcoes=[];};const f=$('#pe_f',el);if(f)f.onchange=e=>{p.formato=e.target.value;};
  const ops=$('#pe_ops',el);const renderOps=()=>{if(!ops)return;ops.innerHTML=(p.opcoes||[]).map((o,i)=>'<div class="pi" data-i="'+i+'"><span class="dot '+o.cor+'" data-c="1"></span><input class="input sm" value="'+esc(o.nome)+'" style="padding:3px 6px;font-size:13px;border:none;background:transparent;flex:1"><span class="sub" data-rm="1" style="cursor:pointer">✕</span></div>').join('');
    $$('.pi',ops).forEach(d=>{const o=p.opcoes[+d.dataset.i];$('input',d).oninput=e=>{o.nome=e.target.value;};$('[data-rm]',d).onclick=()=>{p.opcoes.splice(+d.dataset.i,1);renderOps();};$('[data-c]',d).onclick=()=>{o.cor=CORES_TAG[(CORES_TAG.indexOf(o.cor)+1)%CORES_TAG.length];renderOps();};});};renderOps();
  const add=$('#pe_add',el);if(add)add.onclick=()=>{p.opcoes.push({id:sid(),nome:'Opção '+(p.opcoes.length+1),cor:corAleatoria()});renderOps();const last=$$('#pe_ops input',el).pop();last&&last.focus();last&&last.select();};}
function propsMenu(st,anchor){const v=visaoAtual(st);const vis=propsVisiveis(st,v).map(p=>p.id);const html='<div class="plbl">PROPRIEDADES NA VISÃO</div>'+propsDe(st.base).map(p=>'<div class="pi" data-p="'+p.id+'"><span class="ico">'+ICO[p.tipo]+'</span><span>'+esc(p.nome)+'</span><span class="sub">'+(vis.includes(p.id)?'👁':'◌')+'</span></div>').join('')+'<div class="psep"></div><div class="pi" data-p="__add"><span class="ico">+</span><span>Nova propriedade</span></div>';
  const el=pop(anchor,html,{onFechar:()=>{baseSalvar(st);baseRender(st);}});$$('.pi',el).forEach(d=>d.onclick=()=>{if(d.dataset.p==='__add'){popFechar();return propNova(st,anchor);}const id=d.dataset.p;v.props=vis.includes(id)?vis.filter(x=>x!==id):propsDe(st.base).map(p=>p.id).filter(x=>vis.includes(x)||x===id);propsMenu(st,anchor);});}

// ---------- visões ----------
function visaoNova(st){const tipos=[['tabela','Tabela'],['kanban','Kanban'],['lista','Lista'],['galeria','Galeria'],['calendario','Calendário']];const bg=modal('<div class="modal-h">Nova visão</div><div class="modal-b"><div class="field"><label>Nome</label><input class="input" id="vn_n" placeholder="Ex.: Por responsável"></div><div class="field"><label>Tipo</label><select class="input" id="vn_t">'+tipos.map(t=>'<option value="'+t[0]+'">'+t[1]+'</option>').join('')+'</select></div></div><div class="modal-f"><button class="btn btn-ghost" onclick="fecharModal()">Cancelar</button><button class="btn btn-primary" id="vn_ok">Criar</button></div>');
  $('#vn_ok',bg).onclick=async()=>{const t=$('#vn_t',bg).value;const v={id:sid(),nome:$('#vn_n',bg).value.trim()||tipos.find(x=>x[0]===t)[1],tipo:t,props:null};if(t==='kanban')v.agrupar=(propsDe(st.base).find(p=>p.tipo==='status'||p.tipo==='select')||{}).id;if(t==='calendario')v.calendarioPor=(propsDe(st.base).find(p=>p.tipo==='data')||{}).id;st.base.visoes.push(v);st.visaoId=v.id;fecharModal(bg);await baseSalvar(st);baseRender(st);};}
function visaoMenu(st,anchor){const v=visaoAtual(st);const itens=[{t:'Renomear',ico:'✎',f:async()=>{const n=await perguntar('Nome da visão',v.nome);if(n!=null){v.nome=n;baseSalvar(st);baseRender(st);}}},{lbl:'Tipo'}].concat([['tabela','Tabela'],['kanban','Kanban'],['lista','Lista'],['galeria','Galeria'],['calendario','Calendário']].map(t=>({t:t[1],ico:ICO[t[0]],sub:v.tipo===t[0]?'✓':'',f:()=>{v.tipo=t[0];if(t[0]==='kanban'&&!v.agrupar)v.agrupar=(propsDe(st.base).find(p=>p.tipo==='status'||p.tipo==='select')||{}).id;if(t[0]==='calendario'&&!v.calendarioPor)v.calendarioPor=(propsDe(st.base).find(p=>p.tipo==='data')||{}).id;baseSalvar(st);baseRender(st);}})));
  if(v.tipo==='kanban'||v.tipo==='tabela'||v.tipo==='lista')itens.push({lbl:'Agrupar por'},...propsDe(st.base).filter(p=>['select','status','pessoa','checkbox'].includes(p.tipo)).map(p=>({t:p.nome,ico:ICO[p.tipo],sub:v.agrupar===p.id?'✓':'',f:()=>{v.agrupar=v.agrupar===p.id&&v.tipo!=='kanban'?null:p.id;baseSalvar(st);baseRender(st);}})));
  if(v.tipo==='calendario')itens.push({lbl:'Data do calendário'},...propsDe(st.base).filter(p=>p.tipo==='data').map(p=>({t:p.nome,ico:'📅',sub:v.calendarioPor===p.id?'✓':'',f:()=>{v.calendarioPor=p.id;baseSalvar(st);baseRender(st);}})));
  if(st.base.visoes.length>1)itens.push('-',{t:'Excluir visão',ico:'🗑',danger:true,f:()=>{st.base.visoes=st.base.visoes.filter(x=>x.id!==v.id);st.visaoId=st.base.visoes[0].id;baseSalvar(st);baseRender(st);}});
  menu(anchor,itens);}

// ---------- painel de propriedades de uma linha (página) ----------
async function propsMontar(p,host){if(!host)return;const base=S.byId[p.base_id]?null:null;let b=(S.pagina&&S.pagina._base)||null;if(!b||b.id!==p.base_id){const {data}=await sb.from('hub_paginas').select('id,titulo,esquema,visoes').eq('id',p.base_id).maybeSingle();b=data;}if(!b)return;p._base=b;
  const st={host,base:b,linhas:[p],opts:{},rel:{}};await baseCarregarRelacoes(st);
  const render=()=>{host.innerHTML='<div class="props">'+propsDe(b).map(pr=>{const h=valorHTML(pr,p.props[pr.id],p);return '<div class="prop-row"><div class="pk" data-p="'+pr.id+'"><span class="pt-ico">'+ICO[pr.tipo]+'</span><span>'+esc(pr.nome)+'</span></div><div class="pv'+(h?'':' vazio')+'" data-p="'+pr.id+'">'+(h||'Vazio')+'</div></div>';}).join('')+(podeEditar()?'<div class="props-add" id="pr_add">+ Adicionar propriedade</div>':'')+'</div>';
    $$('.pv',host).forEach(c=>{const pr=propPorId(b,c.dataset.p);c.onclick=()=>{if(!podeEditar())return;celulaEditarPainel(st,c,p,pr,render);};});
    $$('.pk',host).forEach(k=>k.onclick=()=>{if(podeEditar())propEditar(st,k,propPorId(b,k.dataset.p));});
    const a=$('#pr_add',host);if(a)a.onclick=()=>propNova(st,a);};
  const _salvar=baseSalvar;render();
  // ao salvar o esquema pelo painel, re-renderizar
  host._st=Object.assign(st,{host:{innerHTML:'',_st:st},_render:render});
  const origRender=baseRender;}
function celulaEditarPainel(st,c,l,p,render){const refaz=()=>render();const v=l.props[p.id];
  switch(p.tipo){case 'checkbox':linhaSet(st,l,p.id,!v).then(refaz);return;case 'select':case 'status':return selectPicker(c,p,v,async nv=>{await linhaSet(st,l,p.id,nv);refaz();},st);case 'multi':return multiPicker(c,p,arr(v),async nv=>{await linhaSet(st,l,p.id,nv);refaz();},st);case 'pessoa':return pessoaPicker(c,arr(v),async nv=>{await linhaSet(st,l,p.id,nv);refaz();});case 'data':return dataPicker(c,v,async nv=>{await linhaSet(st,l,p.id,nv);refaz();});case 'arquivos':return arquivosPicker(c,arr(v),l,async nv=>{await linhaSet(st,l,p.id,nv);refaz();});case 'relacao':return relacaoPicker(c,p,arr(v),async nv=>{await linhaSet(st,l,p.id,nv);await baseCarregarRelacoes(st);refaz();});case 'criado_em':case 'atualizado_em':return;
    default:{c.classList.remove('vazio');c.innerHTML=p.tipo==='texto'?'<textarea class="input sm" style="width:100%;min-height:60px">'+esc(v==null?'':v)+'</textarea>':'<input class="input sm" type="'+(p.tipo==='numero'?'number':'text')+'" value="'+esc(v==null?'':v)+'" style="width:100%">';const i=$('input,textarea',c);i.focus();i.onclick=e=>e.stopPropagation();const fim=async()=>{let nv=i.value;if(p.tipo==='numero')nv=nv===''?null:+nv;await linhaSet(st,l,p.id,nv);refaz();};i.onblur=fim;i.onkeydown=e=>{if(e.key==='Enter'&&!(p.tipo==='texto'&&e.shiftKey)){e.preventDefault();i.blur();}if(e.key==='Escape'){i.value=v==null?'':v;i.blur();}};}}}
